+#if canImport(UIKit)
+import SwiftUI
+import UIKit
+import MixerUI
+
+@MainActor
+internal struct MixerMeasuredNativeView: UIViewControllerRepresentable {
+    let host: MixerUIHost
+    let installed: AppearanceInstalledV2
+    let dispatch: @MainActor (UIEventEnvelope) -> Bool
+
+    func makeCoordinator() -> Coordinator { Coordinator(host: host) }
+
+    func makeUIViewController(context: Context) -> AppearanceNativeRendererV2 {
+        let renderer = AppearanceNativeRendererV2(installed: installed)
+        let coordinator = context.coordinator
+        renderer.onEnvironmentInvalidated = { [weak renderer, weak coordinator] in
+            guard let renderer else { return }
+            coordinator?.schedule(renderer)
+        }
+        renderer.onRetired = { [weak renderer, weak coordinator] _ in
+            guard let renderer else { return }
+            coordinator?.schedule(renderer)
+        }
+        return renderer
+    }
+
+    func updateUIViewController(_ renderer: AppearanceNativeRendererV2, context: Context) {
+        renderer.onEvent = { _ = dispatch($0) }
+        context.coordinator.schedule(renderer)
+    }
+
+    static func dismantleUIViewController(_ renderer: AppearanceNativeRendererV2, coordinator: Coordinator) {
+        coordinator.mounted = false
+        renderer.onEvent = nil
+        renderer.onEnvironmentInvalidated = nil
+        renderer.onRetired = nil
+    }
+
+    @MainActor final class Coordinator {
+        private weak var host: MixerUIHost?
+        private var scheduled = false
+        var mounted = true
+
+        init(host: MixerUIHost) { self.host = host }
+
+        func schedule(_ renderer: AppearanceNativeRendererV2) {
+            guard mounted, !scheduled else { return }
+            scheduled = true
+            // UIKit can invalidate while laying out. Apply after that layout pass.
+            DispatchQueue.main.async { [weak self, weak renderer] in
+                guard let self else { return }
+                scheduled = false
+                guard mounted, let renderer, let host, host.appearanceError == nil,
+                      let window = renderer.viewIfLoaded?.window, !renderer.view.bounds.isEmpty else { return }
+                let snapshot = host.snapshot
+                let request = host.featureDisplayID
+                do {
+                    if renderer.snapshot?.document.revision != snapshot.document.revision ||
+                        renderer.suspendedReason != nil || renderer.retiredReason != nil {
+                        try renderer.install(snapshot: snapshot)
+                    }
+                } catch {
+                    renderer.retire(error)
+                    host.failAppearance(error)
+                    return
+                }
+                guard let request else { return }
+                CATransaction.begin()
+                CATransaction.setCompletionBlock { [weak self, weak host, weak renderer] in
+                    Task { @MainActor in
+                        guard self?.mounted == true, let host, let renderer,
+                              renderer.viewIfLoaded?.window != nil, renderer.suspendedReason == nil,
+                              renderer.retiredReason == nil, host.snapshot.document.revision == snapshot.document.revision else { return }
+                        host.completeFeatureDisplay(request)
+                    }
+                }
+                window.layoutIfNeeded()
+                window.layer.displayIfNeeded()
+                CATransaction.commit()
+            }
+        }
+    }
+}
+#endif
