+def inspect_paths(authority, swift, sdks, art, jdk, android):
+    args = argparse.Namespace(swift=swift, swift_sdks=sdks, android_artifact=art,
+                              jdk=jdk, android_sdk=android)
+    paths, env = authority.tool_environment(args)
