+def integration_diagnostic(result):
+    """Project only returned memory; never reopen a retained command tree.
+
+    Strings are limited to 96 characters; two cleanup errors and one last
+    command keep the complete JSON below 16KiB even with escaped Unicode.
+    argv, environment, logs and nested receipt/hold payloads are excluded.
+    """
+    def mapping(value):
+        return value if type(value) is dict else {}
+
+    def scalar(value, escaped_limit=480):
+        if type(value) is str:
+            value = value if len(value) <= 96 else value[:93] + '...'
+            while len(json.dumps(value)) > escaped_limit + 2:
+                value = value[:-4] + '...'
+            return value
+        if value is None or type(value) is bool:
+            return value
+        if type(value) is int and -(2**63) <= value < 2**63:
+            return value
+        return None
+
+    def hold_scalar(value):
+        return scalar(value, escaped_limit=96)
+
+    def fields(value, keys, project=scalar):
+        value = mapping(value)
+        return {key: project(value.get(key)) for key in keys}
+
+    result = mapping(result)
+    cleanup = fields(result.get('cleanup'), (
+        'command_custody_terminal', 'owned_scratch_started', 'owned_scratch_removed',
+        'error', 'evidence_persistence_error', 'retention_reason'))
+    records = result.get('command_records')
+    last = mapping(records[-1]) if type(records) is list and records else {}
+    command = fields(last, (
+        'label', 'pid', 'owned_pgid', 'exit_code', 'stop', 'terminal_custody',
+        'direct_child_reaped', 'stdout_eof', 'stderr_eof', 'owned_group_absent',
+        'descriptors_closed'))
+    command['execution_error'] = fields(last.get('execution_error'), ('type', 'message'))
+    command['inner_hold'] = fields(last.get('inner_hold'), (
+        'parent_label', 'operation', 'error', 'retained_cli_tmp'), hold_scalar)
+    command['hold_persistence_error'] = hold_scalar(last.get('hold_persistence_error'))
+    errors = last.get('cleanup_errors')
+    command['cleanup_errors'] = [fields(error, ('operation', 'type', 'message'))
+                                 for error in errors[:2]] if type(errors) is list else []
+    command['group_observation'] = fields(last.get('group_observation'), ('outcome', 'attempts'))
+    diagnostic = fields(result, ('status', 'error'))
+    diagnostic.update(cleanup=cleanup, last_command=command if last else None)
+    return diagnostic
+
+
+def validate_result(value):
+    require(value['status'] == 'passed-java-crosscompile-only', 'Actual integration did not pass')
+    expected = {m + '-' + f for m in ('debug', 'release') for f in ('original', 'relocated', 'exported')}
+    require(set(value['consumers']) == expected and
+            all(v['java_count'] == 21 for v in value['consumers'].values()), 'Incomplete actual six-consumer result')
+    cases = {'sdk', 'adapter', 'descriptor', 'extra-java', 'profile', 'missing-lock'}
+    require(set(value['tamper']) == {'debug', 'release'}, 'Missing actual tamper modes')
+    for mode in ('debug', 'release'):
+        outcomes = value['tamper'][mode]
+        require(len(outcomes) == 6 and {v['case'] for v in outcomes} == cases and
+                all(v['refusal']['status'] == 'error' and v['driver_refusal'] and
+                    v['build_staging_created'] is False for v in outcomes), 'Incomplete actual tamper refusal result')
+    require(value['producer_jobs'] == 2 and value['cleanup']['command_custody_terminal'] is True and
+            value['cleanup']['owned_scratch_removed'] is True, 'Runner concurrency/custody/cleanup differs')
+
