import Foundation
import MixerApple
import MixerUI
import SwiftUI

@main
struct SharedAppearanceApp: App {
    private let host: MixerUIHost

    @MainActor init() {
        let reference = CommandLine.arguments.dropFirst().first.flatMap(Reference.init(rawValue:)) ?? .checklist
        do {
            host = try MixerUIHost(document: reference.document, appearance: UIAppearanceDescriptorCodecV2.mixerDefaultV2())
        } catch {
            fatalError("Installed appearance rejected: \(error)")
        }
    }

    var body: some Scene {
        WindowGroup { Content(host: host) }
    }

    private struct Content: View {
        @ObservedObject var host: MixerUIHost

        var body: some View {
            if let error = host.appearanceError {
                SwiftUI.Text("Appearance unavailable: \(error)")
            } else {
                MixerNativeView(host: host, onAction: { _ in })
                    .ignoresSafeArea()
            }
        }
    }
}

