import MixerUI

enum Reference: String, CaseIterable {
    case checklist, form, queue

    var document: UIDocument {
        switch self {
        case .checklist:
            screen(title: "Checklist", heading: "North Pump Station") {
                MixerUI.Text("progress", "1 of 2 checks complete", style: .headline)
                MixerUI.Toggle("check-seal", "Check seal", value: true, action: "toggle.seal")
                MixerUI.Toggle("check-pressure", "Record pressure", value: false, action: "toggle.pressure")
            }
        case .form:
            screen(title: "Task form", heading: "Inspection details") {
                MixerUI.TextField("task-title", "Task title", value: "Inspect pump seal", action: "edit.title")
                MixerUI.Toggle("follow-up", "Requires follow-up", value: true, action: "toggle.follow-up")
                MixerUI.Button("save", "Save task", action: "save").disabled()
            }
        case .queue:
            screen(title: "Pending queue", heading: "Pending changes") {
                MixerUI.Text("summary", "2 changes awaiting sync", style: .headline)
                MixerUI.Text("queued-task", "Inspect pump seal", style: .body)
                MixerUI.Text("queued-check", "Check seal", style: .body)
                MixerUI.Button("retry", "Retry sync", action: "retry").disabled()
            }
        }
    }

    private func screen(title: String, heading: String,
                        @MixerViewBuilder rows: () -> [UINode]) -> UIDocument {
        MixerUI.Navigation("screen-\(rawValue)", title: title) {
            MixerUI.List("content") {
                MixerUI.Section("section", title: heading, content: rows)
            }
        }.document(revision: 1)
    }
}

