import CoreGraphics
import Foundation
import MixerUI

@main enum ReferenceCoverGeometry {
    static func main() throws {
        let descriptor = try Data(contentsOf: URL(fileURLWithPath: CommandLine.arguments[1]))
        let configuration = try UIAppearanceDescriptorCodecV2.decode(descriptor)
        for reference in Reference.allCases {
            let plan = try prepare(reference.document, configuration)
            try checkNativeRendererAdmission(plan)
            guard let list = plan.node(for: "content"), case let .list(recipe) = list.recipe,
                  let group = recipe.groups.first else { fatalError("Reference list missing") }
            let width = CGFloat(plan.environment.viewport.width64 - 2 * recipe.metrics.outerHorizontal64) / 64
            let height = CGFloat(recipe.rowHeightFloor64) / 64
            precondition(width == 370 && height == 52, "Light/l fixture dimensions changed")
            let inset = CGFloat(recipe.metrics.contentInsets64.trailing) / 64
            let identifiers = group.rowIdentities.map(\.id)
            let bounds = CGRect(x: 0, y: 0, width: width, height: height * CGFloat(identifiers.count))
            let path = try AppearanceNativePathsV2.make(
                UIAppearanceGeometryV2.group(width64: UInt32(width * 64),
                    height64: UInt32(bounds.height * 64), radius64: recipe.metrics.radius64), density1024: 3072)
            let rows = try AppearanceNativeGeometryV2.prepare(identifiers.enumerated().map { index, id in
                .init(key: id, parent: "$root", frame: CGRect(x: 0, y: CGFloat(index)*height,
                    width: width, height: height), index: index)
            }, density1024: 3072)
            let hit = try Dictionary(uniqueKeysWithValues: rows.compactMap { row -> (String, CGRect)? in
                guard let node = plan.node(for: row.key) else { fatalError("Missing row \(row.key)") }
                let carrier: CGRect
                switch node.recipe {
                case let .toggle(_, _, metrics):
                    let hitHeight = CGFloat(metrics.minimumHitHeight64) / 64
                    let hitWidth = CGFloat(metrics.minimumHitWidth64) / 64
                    carrier = CGRect(x: width-inset-hitWidth, y: row.frame.midY-hitHeight/2,
                                     width: hitWidth, height: hitHeight)
                case let .textField(_, _, _, metrics):
                    let hitHeight = CGFloat(metrics.minimumHitHeight64) / 64
                    carrier = CGRect(x: inset, y: row.frame.midY-hitHeight/2,
                                     width: width-2*inset, height: hitHeight)
                default: return nil
                }
                try AppearanceNativeGeometryV2.validateCarrier(carrier, rowBounds: row.frame)
                return (row.key, carrier)
            })
            switch reference {
            case .checklist:
                try overlap("check-seal", blockedBy: "check-pressure", width: 63, hit, bounds, path)
                let last = hit["check-pressure"]!.insetBy(dx: -12, dy: -12)
                precondition(last.maxY-bounds.maxY == 8)
                expectRefusal("Checklist last toggle escapes group bounds by 8pt") {
                    try validate(last, [], bounds, path)
                }
            case .form:
                try overlap("follow-up", blockedBy: "task-title", width: 75, hit, bounds, path)
            case .queue:
                precondition(hit.isEmpty)
                print("PASS Queue exact document resolves and has no toggle cover")
            }
        }
        try nestedNegatives(configuration)
    }

    private static func prepare(_ document: UIDocument, _ configuration: UIAppearanceConfigurationV2) throws -> UIResolvedAppearancePlanV2 {
        let environment = UIAppearanceEnvironmentV2(scheme: .light, direction: .leftToRight,
            profile: .l, density1024: 3072, viewport: .init(width64: 402*64, height64: 874*64),
            safeArea64: .init(top: 0, leading: 0, bottom: 0, trailing: 0), localeIdentifier: "en-US",
            accessibility: .init(boldText: false, increasedContrast: false, reduceMotion: false), generation: 1)
        var reconciler = UIReconciler()
        try reconciler.apply(document)
        return try UIAppearanceResolverV2.prepare(snapshot: reconciler.currentSnapshot(),
            configuration: configuration, environment: environment, platform: .iOS)
    }

    private static func overlap(_ owner: String, blockedBy other: String, width: CGFloat, _ hit: [String: CGRect],
                                _ bounds: CGRect, _ path: CGPath) throws {
        let cover = hit[owner]!.insetBy(dx: -12, dy: -12)
        let blocker = hit[other]!
        try validate(cover, [], bounds, path)
        let intersection = cover.intersection(blocker)
        precondition(intersection.height == 4 && intersection.width == width)
        expectRefusal("\(owner) intersects \(other) carrier by \(intersection.width)×\(intersection.height)pt") {
            try validate(cover, [blocker], bounds, path)
        }
    }

    private static func validate(_ cover: CGRect, _ foreground: [CGRect], _ bounds: CGRect, _ path: CGPath) throws {
        try AppearanceNativeGeometryV2.validateCover(cover, foreground: foreground,
            groupBounds: bounds, groupPath: path, density1024: 3072)
    }

    private static func nestedNegatives(_ configuration: UIAppearanceConfigurationV2) throws {
        let button = MixerUI.Button("button", "Button", action: "button").uiNode
        let field = MixerUI.TextField("field", "Field", value: "Value", action: "edit").uiNode
        let toggle = MixerUI.Toggle("toggle", "Toggle", value: true, action: "toggle").uiNode
        for control in [button, field, toggle] {
            let row = UINode(id: "row", kind: .vStack,
                children: [UINode(id: "wrapper", kind: .hStack, children: [control])])
            let document = UIDocument(revision: 1, root: UINode(id: "list", kind: .list, children: [row]))
            let plan = try prepare(document, configuration)
            expectRefusal("renderer refuses nested \(control.kind)") { try checkNativeRendererAdmission(plan) }
        }
        let text = MixerUI.Text("text", "Text").uiNode
        for kind in [NodeKind.list, .navigation] {
            let nested = UINode(id: "nested", kind: kind, children: [text])
            let wrapper = UINode(id: "wrapper", kind: .vStack, children: [nested])
            let document = UIDocument(revision: 1, root: UINode(id: "list", kind: .list, children: [wrapper]))
            expectRefusal("resolver refuses nested \(kind)") { _ = try prepare(document, configuration) }
        }
    }

    private static func expectRefusal(_ name: String, _ operation: () throws -> Void) {
        do {
            try operation()
            fatalError("Unexpected admission: \(name)")
        } catch UIAppearanceErrorV2.unsupportedNativeOperation {
            print("PASS \(name)")
        } catch {
            fatalError("Unexpected error for \(name): \(error)")
        }
    }
}

