import CoreGraphics
import Foundation
import MixerUI

@main enum ReferenceCoverPositive {
    static func main() throws {
        let config = try UIAppearanceDescriptorCodecV2.decode(
            Data(contentsOf: URL(fileURLWithPath: CommandLine.arguments[1])))
        try observedRefusals(config)
        for profile in [UISharedTextProfileV1.l, .a1] {
            for reference in Reference.allCases {
                try check(reference, profile: profile, config: config)
            }
        }
    }

    static func plan(_ reference: Reference, profile: UISharedTextProfileV1, config: UIAppearanceConfigurationV2) throws -> UIResolvedAppearancePlanV2 {
        var reconciler = UIReconciler()
        try reconciler.apply(reference.document)
        let environment = UIAppearanceEnvironmentV2(scheme: profile == .l ? .light : .dark, direction: .leftToRight,
            profile: profile, density1024: 3072, viewport: .init(width64: 402 * 64, height64: 874 * 64),
            safeArea64: .init(top: 63 * 64, leading: 0, bottom: 34 * 64, trailing: 0), localeIdentifier: "en-US",
            accessibility: .init(boldText: false, increasedContrast: false, reduceMotion: false), generation: 1)
        return try UIAppearanceResolverV2.prepare(snapshot: reconciler.currentSnapshot(),
            configuration: config, environment: environment, platform: .iOS)
    }

    static func observedRefusals(_ config: UIAppearanceConfigurationV2) throws {
        let checklist = try plan(.checklist, profile: .l, config: config)
        let form = try plan(.form, profile: .l, config: config)
        let bounds = CGRect(x: 0, y: 0, width: 370, height: 156)
        for (plan, cover, blockers) in [
            (checklist, CGRect(x: 279, y: 96, width: 87, height: 52), [CGRect]()),
            (form, CGRect(x: 279, y: 44, width: 87, height: 52), [CGRect(x: 16, y: 4, width: 338, height: 44)])
        ] {
            guard case let .list(recipe)? = plan.node(for: "content")?.recipe else { fatalError("Missing list") }
            let path = try outline(bounds, radius: recipe.metrics.radius64)
            do {
                try AppearanceNativeGeometryV2.validateCover(cover, foreground: blockers, groupBounds: bounds,
                    groupPath: path, density1024: 3072)
                fatalError("Captured baseline geometry unexpectedly admitted")
            } catch UIAppearanceErrorV2.unsupportedNativeOperation {}
        }
        print("PASS both exact light/l native refusal rectangles")
    }

    static func check(_ reference: Reference, profile: UISharedTextProfileV1, config: UIAppearanceConfigurationV2) throws {
        let plan = try plan(reference, profile: profile, config: config)
        try checkNativeRendererAdmission(plan)
        guard case let .list(recipe)? = plan.node(for: "content")?.recipe,
              let group = recipe.groups.first else { fatalError("Missing list group") }
        let width = CGFloat(plan.environment.viewport.width64 - 2 * recipe.metrics.outerHorizontal64) / 64
        let inset = CGFloat(recipe.metrics.contentInsets64.trailing) / 64
        let rows = group.rowIdentities.map(\.id)
        // Light rows and native switch size come from the actual refusal. The a1
        // height models the retained iOS UILabel/AX measurement (33.421875 + 30).
        let baselineHeight = profile == .l ? CGFloat(recipe.rowHeightFloor64) / 64 : 63.421875
        precondition(width == 370 && inset == 16 && recipe.rowHeightFloor64 == (profile == .l ? 52 : 59) * 64)
        var y: CGFloat = 0
        var placements: [AppearanceNativeGeometryV2.Placement] = []
        var carriers: [String: CGRect] = [:]
        var labels: [String: CGRect] = [:]
        var covers: [String: CGRect] = [:]
        for (index, id) in rows.enumerated() {
            guard let node = plan.node(for: id) else { fatalError("Missing row \(id)") }
            var height = baselineHeight
            switch node.recipe {
            case let .toggle(_, _, metrics):
                let carrierWidth = CGFloat(metrics.minimumHitWidth64) / 64
                var carrier = CGRect(x: width - inset - carrierWidth, y: 0, width: carrierWidth, height: 28)
                let row = try AppearanceNativeGeometryV2.toggleRow(height: height, carrier: carrier,
                    groupWidth: width, radius64: recipe.metrics.radius64, first: index == 0,
                    last: index == rows.count - 1, density1024: 3072)
                height = row.height
                carrier.origin.y = row.center - carrier.height / 2
                carriers[id] = carrier
                let pad = AppearanceNativeGeometryV2.toggleCoverPadding
                let cover = carrier.insetBy(dx: -pad, dy: -pad)
                precondition(cover.size == CGSize(width: 87, height: 52))
                covers[id] = cover
                // A modeled left-aligned label region. Attached UILabels are
                // measured and checked by the independent native probe.
                labels[id] = CGRect(x: inset, y: row.center - 17, width: 240, height: 34)
            case .textField, .button:
                carriers[id] = CGRect(x: inset, y: (height - 44) / 2, width: width - 2 * inset, height: 44)
            default:
                break
            }
            placements.append(.init(key: id, parent: "group", frame: CGRect(x: 0, y: y, width: width, height: height), index: index))
            y += height
        }
        placements.insert(.init(key: "group", parent: "$root", frame: CGRect(x: 16, y: 207 + 13/64, width: width, height: y), index: 0), at: 0)
        let final = Dictionary(uniqueKeysWithValues: try AppearanceNativeGeometryV2.prepare(placements,
            density1024: 3072).map { ($0.key, $0.frame) })
        let groupBounds = CGRect(origin: .zero, size: final["group"]!.size)
        let path = try outline(CGRect(x: 0, y: 0, width: width, height: y), radius: recipe.metrics.radius64)
        for (id, carrier) in carriers {
            try AppearanceNativeGeometryV2.validateCarrier(carrier, rowBounds: CGRect(origin: .zero, size: final[id]!.size))
        }
        for id in rows where covers[id] != nil {
            func inGroup(_ rect: CGRect, rowID: String) -> CGRect { rect.offsetBy(dx: 0, dy: final[rowID]!.minY) }
            let cover = inGroup(covers[id]!, rowID: id)
            let blockers = carriers.filter { $0.key != id }.map { inGroup($0.value, rowID: $0.key) }
                + labels.map { inGroup($0.value, rowID: $0.key) }
            try AppearanceNativeGeometryV2.validateCover(cover, foreground: blockers, groupBounds: groupBounds,
                groupPath: path, density1024: 3072)
            print("PASS \(reference.rawValue)/\(profile) \(id) \(cover) group=\(groupBounds) logicalHeight=\(y)")
        }
        if reference == .queue {
            precondition(covers.isEmpty && y == baselineHeight * CGFloat(rows.count))
            print("PASS queue/\(profile) unchanged row geometry")
        }
        if reference == .form {
            precondition(y == baselineHeight * 3, "Interior toggle must preserve the reference row cadence")
        }
    }

    static func outline(_ bounds: CGRect, radius: UInt32) throws -> CGPath {
        try AppearanceNativePathsV2.make(UIAppearanceGeometryV2.group(
            width64: UIAppearanceGeometryV2.measuredExtent64(Double(bounds.width)),
            height64: UIAppearanceGeometryV2.measuredExtent64(Double(bounds.height)), radius64: radius), density1024: 3072)
    }
}

