import UIKit
import XCTest

final class SharedAppearanceCapture: XCTestCase {
    @MainActor func testChecklist() throws { try capture("checklist", heading: "North Pump Station") }
    @MainActor func testForm() throws { try capture("form", heading: "Inspection details") }
    @MainActor func testQueue() throws { try capture("queue", heading: "Pending changes") }

    private struct Element: Encodable {
        let role: String
        let roleCode: UInt
        let identifier: String
        let label: String
        let value: String?
        let enabled: Bool
        let frame: [Double]?
        let children: [Element]

        @MainActor init(_ element: XCUIElement) {
            let type = element.elementType
            role = switch type {
            case .application: "application"
            case .window: "window"
            case .scrollView: "scrollView"
            case .staticText: "staticText"
            case .switch: "switch"
            case .textField: "textField"
            case .button: "button"
            case .other: "other"
            default: String(describing: type)
            }
            roleCode = type.rawValue
            identifier = element.identifier
            label = element.label
            value = element.value.map { String(describing: $0) }
            enabled = element.isEnabled
            frame = Self.frame(element.frame)
            children = element.children(matching: .any).allElementsBoundByIndex.map { Element($0) }
        }

        static func frame(_ rect: CGRect) -> [Double]? {
            let components = [rect.origin.x, rect.origin.y, rect.width, rect.height].map(Double.init)
            return components.allSatisfy(\.isFinite) ? components : nil
        }
    }

    private struct Observation: Encodable {
        let launchArguments: [String]
        let requestedProfile: String
        let runtime: String
        let foreground: Bool
        let headingObserved: Bool
        let windowFramePoints: [Double]?
        let screenshotWidthPixels: Int
        let screenshotHeightPixels: Int
        let hierarchy: Element
    }

    private struct ExpectedPacket: Decodable {
        let document: Document

        struct Document: Decodable { let root: Node }

        struct Node: Decodable {
            let id: String
            let kind: String
            let children: [Node]

            var leaves: [Node] { children.isEmpty ? [self] : children.flatMap(\.leaves) }

            var nativeRole: XCUIElement.ElementType? {
                switch kind {
                case "text": .staticText
                case "textField": .textField
                case "toggle": .switch
                case "button": .button
                default: nil
                }
            }
        }
    }

    @MainActor private func capture(_ screen: String, heading: String) throws {
        let process = ProcessInfo.processInfo
        let runtime = process.operatingSystemVersion
        guard runtime.majorVersion == 26 && runtime.minorVersion == 5 else {
            XCTFail("SharedAppearance V2 requires iOS 26.5")
            return
        }

        let profile = try XCTUnwrap(process.environment["MIXER_CAPTURE_PROFILE"])
        guard ["light/l", "dark/a1"].contains(profile) else {
            XCTFail("Unexpected capture profile \(profile)")
            return
        }
        let file = try XCTUnwrap(Bundle(for: Self.self).url(forResource: "\(screen).packet", withExtension: "json"))
        let expected = try Data(contentsOf: file)
        let document = try JSONDecoder().decode(ExpectedPacket.self, from: expected).document
        XCTAssertEqual(document.root.id, "screen-\(screen)")
        let name = "\(screen)-\(profile.replacingOccurrences(of: "/", with: "-"))"
        attach(expected, type: "public.json", name: "\(name)-expected-packet.json")

        let app = XCUIApplication(bundleIdentifier: "dev.mixer.sharedappearance")
        app.launchArguments = [screen]
        app.launch()
        defer { app.terminate() }

        let headingObserved = app.staticTexts.matching(NSPredicate(format: "label == %@", heading))
            .firstMatch.waitForExistence(timeout: 10)
        let foreground = app.state == .runningForeground
        let window = app.windows.firstMatch
        let viewport = window.exists ? window.frame : .null

        let screenshot = XCUIScreen.main.screenshot()
        attach(screenshot.pngRepresentation, type: "public.png", name: "\(name).png")
        attach(Data(app.debugDescription.utf8), type: "public.plain-text", name: "\(name)-ax.txt")

        let image = try XCTUnwrap(screenshot.image.cgImage)
        let observation = Observation(launchArguments: app.launchArguments, requestedProfile: profile,
            runtime: process.operatingSystemVersionString, foreground: foreground, headingObserved: headingObserved,
            windowFramePoints: Element.frame(viewport), screenshotWidthPixels: image.width,
            screenshotHeightPixels: image.height, hierarchy: Element(app))
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        attach(try encoder.encode(observation), type: "public.json", name: "\(name)-ax.json")

        XCTAssertTrue(foreground)
        XCTAssertTrue(headingObserved, "Missing native screen heading \(heading)")
        XCTAssertFalse(viewport.isNull || viewport.isEmpty)
        XCTAssertFalse(app.staticTexts.matching(NSPredicate(format: "label BEGINSWITH %@", "Appearance unavailable:")).firstMatch.exists)
        for node in document.root.leaves {
            let role = try XCTUnwrap(node.nativeRole, "Missing native role for \(node.kind)")
            let element = app.descendants(matching: role)
                .matching(NSPredicate(format: "identifier == %@", node.id)).firstMatch
            XCTAssertTrue(element.exists, "Missing \(role) for \(node.id)")
            if element.exists {
                let frame = element.frame
                XCTAssertFalse(frame.isEmpty || !frame.intersects(viewport), "Outside viewport: \(node.id)")
            }
        }
    }

    private func attach(_ data: Data, type: String, name: String) {
        let attachment = XCTAttachment(data: data, uniformTypeIdentifier: type)
        attachment.name = name
        attachment.lifetime = .keepAlways
        add(attachment)
    }
}

