import XCTest

final class SharedAppearanceInteraction: XCTestCase {
    @MainActor func testChecklist() throws {
        let app = XCUIApplication(bundleIdentifier: "dev.mixer.sharedappearance")
        app.launchArguments = ["checklist"]
        app.launch()
        // Leave the process running so root can export the attached-view receipt.
        XCTAssertTrue(app.staticTexts["North Pump Station"].waitForExistence(timeout: 10))
        try exercise(app.switches["check-seal"], label: "Check seal", initial: "1")
        try exercise(app.switches["check-pressure"], label: "Record pressure", initial: "0")
    }

    @MainActor func testForm() throws {
        let app = XCUIApplication(bundleIdentifier: "dev.mixer.sharedappearance")
        app.launchArguments = ["form"]
        app.launch()
        XCTAssertTrue(app.staticTexts["Inspection details"].waitForExistence(timeout: 10))
        let field = app.textFields["task-title"]
        let save = app.buttons["save"]
        XCTAssertTrue(field.exists && field.isEnabled && field.isHittable)
        XCTAssertTrue(save.exists && !save.isEnabled)
        try exercise(app.switches["follow-up"], label: "Requires follow-up", initial: "1")
        field.tap()
        field.typeText("x")
        let edited = try XCTUnwrap(field.value as? String)
        XCTAssertEqual(edited.replacingOccurrences(of: "x", with: ""), "Inspect pump seal")
        XCTAssertTrue(edited.contains("x"))
        capture("form-after-field-tap")
    }

    @MainActor private func exercise(_ control: XCUIElement, label: String, initial: String) throws {
        XCTAssertTrue(control.exists && control.isEnabled && control.isHittable)
        XCTAssertEqual(control.label, label)
        XCTAssertEqual(control.value as? String, initial)
        attachAX(control, "\(control.identifier)-initial")
        capture("\(control.identifier)-unpressed")
        XCTContext.runActivity(named: "\(control.identifier)-physical-hold-1.2s") { _ in
            control.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5)).press(forDuration: 1.2)
        }
        let beforeTap = try XCTUnwrap(control.value as? String)
        XCTAssertTrue(["0", "1"].contains(beforeTap))
        control.tap()
        let expected = beforeTap == "1" ? "0" : "1"
        let changed = XCTNSPredicateExpectation(predicate: NSPredicate(format: "value == %@", expected), object: control)
        XCTAssertEqual(XCTWaiter.wait(for: [changed], timeout: 3), .completed)
        attachAX(control, "\(control.identifier)-after-tap")
        capture("\(control.identifier)-after-tap")
    }

    @MainActor private func attachAX(_ element: XCUIElement, _ name: String) {
        let result = XCTAttachment(string: element.debugDescription)
        result.name = name
        result.lifetime = .keepAlways
        add(result)
    }

    @MainActor private func capture(_ name: String) {
        let result = XCTAttachment(screenshot: XCUIScreen.main.screenshot())
        result.name = name
        result.lifetime = .keepAlways
        add(result)
    }
}

