package dev.mixer.android;

import android.app.Activity;
import android.content.res.Configuration;
import android.graphics.Canvas;
import android.text.Layout;
import android.widget.Switch;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Objects;

public final class SwitchLabelPaintControl {
    private static final int BLACK = 0xff000000;
    private static final int WHITE = 0xffffffff;
    private static final int STALE_INK = 0xffab2390;

    private static void check(boolean condition, String reason) {
        if (!condition) throw new AssertionError(reason);
    }

    private static Field field(Class<?> type, String name) throws Exception {
        Field field = type.getDeclaredField(name);
        field.setAccessible(true);
        return field;
    }

    private static Method method(Class<?> type, String name) throws Exception {
        Method method = type.getDeclaredMethod(name);
        method.setAccessible(true);
        return method;
    }

    private static void verify(NativeRenderer renderer, Switch view, String state,
                               int knownLabel, int stale, boolean fixed) {
        check(renderer.view("toggle") == view, "toggle replaced during " + state);
        var record = renderer.inspectV2().get("toggle");
        int authored = NativeAppearanceViewsV2.color(NativeAppearanceViewsV2.togglePaint(record).label());
        int current = view.getCurrentTextColor();
        check(authored == knownLabel, "wrong descriptor label for " + state);
        check(current == authored, "resolved widget color differs from descriptor for " + state);
        Layout layout = Objects.requireNonNull(view.getLayout());
        check(layout.getPaint().getColor() == stale, "unexpected pre-draw layout color for " + state);
        int[] drawn = {0};
        int[] sampled = {0};
        float[] translation = {0, 0};
        int width = view.getWidth();
        int height = view.getHeight();
        var canvas = new Canvas();
        ConcreteHostProbe.reset();
        ConcreteHostProbe.hook = (name, phase) -> {
            var event = ConcreteHostProbe.lastEvent();
            if (name.equals("Layout.draw") && phase.equals("entry") && event.receiver == layout) {
                check(event.productionFrames.stream().anyMatch(site ->
                    site.className().endsWith("$NativeSwitch") && site.methodName().equals("onDraw")),
                    "layout draw did not originate from production NativeSwitch");
                drawn[0] = layout.getPaint().getColor();
                sampled[0]++;
                translation[0] = canvas.translationX;
                translation[1] = canvas.translationY;
            }
        };
        try {
            view.draw(canvas);
        } finally {
            ConcreteHostProbe.reset();
        }
        System.out.printf("%s current=%08X before=%08X drawn=%08X after=%08X geometry=%dx%d translate=%.1f,%.1f%n",
            state, current, stale, drawn[0], layout.getPaint().getColor(), width, height, translation[0], translation[1]);
        check(sampled[0] == 1, "expected one label draw for " + state);
        check(drawn[0] == (fixed ? authored : stale), "wrong measured label ink for " + state);
        check(layout.getPaint().getColor() == stale, "draw leaked paint color for " + state);
        check(canvas.saves == 1 && canvas.translationX == 0 && canvas.translationY == 0,
            "draw leaked canvas transform for " + state);
        check(translation[0] == 0 && translation[1] == (height - layout.getHeight()) / 2f &&
              view.getWidth() == width && view.getHeight() == height, "label geometry changed for " + state);
    }

    public static void main(String[] args) throws Exception {
        boolean fixed = args[0].equals("corrected");
        var ownerTests = NativeOwnerV2ConcreteHostTests.class;
        field(ownerTests, "descriptor").set(null, Files.readAllBytes(Path.of(args[1])));
        Class<?> fixtureType = Class.forName(ownerTests.getName() + "$Fixture");
        var fixtureConstructor = fixtureType.getDeclaredConstructor();
        fixtureConstructor.setAccessible(true);
        try (AutoCloseable fixture = (AutoCloseable) fixtureConstructor.newInstance()) {
            Method ready = method(fixtureType, "ready");
            Activity activity = (Activity) field(fixtureType, "activity").get(fixture);
            activity.resources.configuration.uiMode = Configuration.UI_MODE_NIGHT_YES;
            ready.invoke(fixture);
            var renderer = (NativeRenderer) method(fixtureType, "renderer").invoke(fixture);
            var view = (Switch) renderer.view("toggle");
            verify(renderer, view, "dark-enabled-off", WHITE, BLACK, fixed);
            Layout initial = view.getLayout();

            int prepares = NativeBridge.prepareCalls;
            view.setEnabled(false);
            check(!view.isEnabled() && !view.performClick() && !view.isChecked()
                    && NativeBridge.prepareCalls == prepares, "disabled action/state");
            check(view.getLayout() == initial, "disabled state replaced layout");
            verify(renderer, view, "dark-disabled-off", 0xff555556, BLACK, fixed);
            view.setEnabled(true);
            view.getLayout().getPaint().setColor(STALE_INK);
            view.setPressed(true);
            check(view.isEnabled() && view.isPressed() && !view.isChecked() && view.getLayout() == initial,
                "pressed state or layout");
            verify(renderer, view, "dark-pressed-reused", WHITE, STALE_INK, fixed);
            view.setPressed(false);
            verify(renderer, view, "dark-released-reused", WHITE, STALE_INK, fixed);

            activity.resources.configuration.uiMode = Configuration.UI_MODE_NIGHT_NO;
            activity.hostConfigurationChanged();
            ready.invoke(fixture);
            verify(renderer, view, "light-enabled-off-reused", BLACK, STALE_INK, fixed);
            view.setEnabled(false);
            verify(renderer, view, "light-disabled-off-reused", 0xffbfbfbf, STALE_INK, fixed);
            view.setEnabled(true);

            activity.resources.configuration.uiMode = Configuration.UI_MODE_NIGHT_YES;
            activity.hostConfigurationChanged();
            ready.invoke(fixture);
            verify(renderer, view, "dark-enabled-off-after-light", WHITE, STALE_INK, fixed);
        }
    }
}

